"use client";

import { loadFont as loadPlexMono } from "@remotion/google-fonts/IBMPlexMono";
import { loadFont as loadInstrument } from "@remotion/google-fonts/InstrumentSans";
import type React from "react";
import { Fragment, useId } from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  type CutStatElementId,
  claimWords,
  cutStatTimeline,
  DEFAULT_LABEL,
} from "./timeline";

const instrument = loadInstrument("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const plex = loadPlexMono("normal", { weights: ["500"], subsets: ["latin"] });

export interface CutStatProps {
  value?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  label?: string;
  caption?: string;
  fromLabel?: string;
  toLabel?: string;
  accent?: string;
  /** Text color of the number, claim and readout; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the number and claim. Load it yourself; Instrument Sans by default. */
  fontFamily?: string;
  /** Weight of the number. */
  fontWeight?: number;
  /** Frames between the claim's words as they rise in. */
  stagger?: number;
  /** Size of the number block, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Film grain over the bar. */
  grain?: boolean;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the bar, the cut, the readout swap, the flash,
   * the release, the claim's words and the caption, by the ids in
   * `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<CutStatElementId>;
}

const MESH = ["#ecdcf2", "#8796ee", "#2e45b7", "#0e1645"] as const;
const MESH_BG = "#0a0d24";
const BLOBS: [number, number][] = [
  [16, 20],
  [84, 26],
  [72, 86],
  [22, 80],
  [52, 48],
  [92, 62],
];

const PALETTES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F4F3F0",
    muted: "#8E8D94",
    fieldFg: "#F6F4FF",
    fieldMuted: "rgba(246,244,255,0.66)",
    edge: "#F6F4FF",
    tick: "rgba(255,255,255,0.09)",
    fieldTick: "rgba(255,255,255,0.16)",
    fieldBg: MESH_BG,
    blobs: [MESH[3], MESH[3], MESH[1], MESH[2], MESH[1], MESH[0]],
  },
  light: {
    bg: "#F5F4F0",
    fg: "#111113",
    muted: "#6E6C67",
    fieldFg: "#0E1238",
    fieldMuted: "rgba(14,18,56,0.6)",
    edge: "#111113",
    tick: "rgba(17,17,19,0.1)",
    fieldTick: "rgba(14,18,56,0.16)",
    fieldBg: "#DCE0F8",
    blobs: ["#c9d0f7", "#a9b4f2", MESH[1], "#b3bdf4", MESH[0], "#f3eef9"],
  },
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_CUT = Easing.bezier(0.72, 0, 0.16, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

function estimateEm(text: string) {
  let w = 0;
  for (const ch of text) {
    if (/[0-9]/.test(ch)) w += 0.56;
    else if (ch === "%") w += 0.78;
    else if (/[.,]/.test(ch)) w += 0.24;
    else if (/[−\-+×x]/.test(ch)) w += 0.52;
    else if (ch === "$" || ch === "€") w += 0.56;
    else if (ch === " ") w += 0.22;
    else w += 0.56;
  }
  return w;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `grain-${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{
        position: "absolute",
        inset: 0,
        opacity,
        mixBlendMode: "overlay",
      }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.8"
          numOctaves={2}
          seed={11}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 1 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function CutStat(props: CutStatProps) {
  const {
    value = 44,
    decimals = 0,
    prefix = "−",
    suffix = "%",
    label = DEFAULT_LABEL,
    caption = "vs. keyframing every scene by hand",
    fromLabel = "Before",
    toLabel = "With remocn",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = instrument.fontFamily,
    fontWeight = 500,
    scale: zoom = 1,
    delay = 0,
    grain = true,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const raw = Math.max(0, useSceneFrame() - delay);
  const frame = raw * speed;
  const { width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    cutStatTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const introEl = tl.get("intro");
  const fillEl = tl.get("fill");
  const ticksEl = tl.get("ticks");
  const cutEl = tl.get("cut");
  const swapEl = tl.get("swap");
  const flashEl = tl.get("flash");
  const releaseEl = tl.get("release");
  const captionEl = tl.get("caption");
  const p = PALETTES[theme];
  const fg = ink ?? p.fg;

  const portrait = height > width * 1.1;
  const u = Math.min(width, height) / 720;
  const v = Math.min(95, Math.max(5, value));
  const along = portrait ? height : width;

  const intro = interpolate(frame, [introEl.start, introEl.end], [0, 1], CLAMP);
  const fill = interpolate(frame, [fillEl.start, fillEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const cut = interpolate(frame, [cutEl.start, cutEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_CUT,
  });
  const flash = interpolate(
    frame,
    [flashEl.start, flashEl.start + flashEl.beat("peak"), flashEl.end],
    [0, 1, 0],
    CLAMP,
  );
  const drift = interpolate(raw, [0, durationInFrames], [0, 1], CLAMP);
  const cutPx = (along * v * cut) / 100;
  const remaining = 100 - v * cut;
  const counted = v * cut;
  const fmt = (n: number) => n.toFixed(decimals);
  const swapT = interpolate(frame, [swapEl.start, swapEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const margin = (portrait ? 56 : 52) * u;
  const zone = (along * v) / 100;
  const finalText = `${prefix}${fmt(v)}${suffix}`;
  const em = estimateEm(finalText);
  const roomW = portrait
    ? width - margin * 2
    : Math.max(zone, width * 0.36) - margin * 1.6;
  const statFs = Math.min(
    (portrait ? 300 : 236) * u,
    roomW / em,
    portrait ? Math.max(zone, height * 0.3) * 0.5 : Infinity,
  );
  const words = claimWords(label);
  const wordT = (i: number) => {
    const e = tl.get(`word:${i}`);
    return interpolate(frame, [e.start, e.end], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  };
  const capT = interpolate(frame, [captionEl.start, captionEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const transparent = background === "transparent";
  const labelFs = 14 * u;
  const blobs = BLOBS.map(([x, y], i) => {
    const c = p.blobs[i];
    const dx = Math.sin(i * 1.7 + drift * 2.2) * 3;
    const dy = Math.cos(i * 1.3 + drift * 2.2) * 3;
    return `radial-gradient(85% 95% at ${x + dx}% ${y + dy}%, ${c} 0%, transparent 68%)`;
  });
  blobs[2] = `radial-gradient(85% 95% at ${72 + drift * 3}% ${86 - drift * 3}%, color-mix(in oklab, ${accent} ${theme === "dark" ? 70 : 45}%, ${MESH[1]}) 0%, transparent 68%)`;

  const shut = cutPx + along * (1 - fill);
  const fieldClip = portrait
    ? `inset(0 0 ${shut}px 0)`
    : `inset(0 ${shut}px 0 0)`;
  const edgePos = along - shut;
  const edgeO =
    fill < 1
      ? fill > 0.02 && fill < 0.98
        ? 1
        : 0
      : cut <= 0
        ? 0
        : cut < 1
          ? 1
          : 0.35 + flash * 0.65;

  // The edge sweeps by a transform from where the cut ends: an edge moved by
  // `left` rounds to whole pixels and steps unevenly. Within 1/128px of that
  // place the old layout path is kept, so the settled edge is untouched.
  const edgeRest = along * (1 - v / 100);
  const edgeTravel = Math.abs(edgePos - edgeRest) >= 1 / 128;
  const edgeAt = edgeTravel ? edgeRest : edgePos;

  const release = interpolate(frame, [releaseEl.start, releaseEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const clipAt = edgePos * (1 - release);
  const statClip = portrait
    ? `inset(${clipAt}px 0 0 0)`
    : `inset(0 0 0 ${clipAt}px)`;

  const scaleT = interpolate(
    frame,
    [ticksEl.start, ticksEl.end],
    [0, 1],
    CLAMP,
  );
  const scale = (line: string, text: string) => (
    <div style={{ position: "absolute", inset: 0, opacity: scaleT }}>
      {Array.from({ length: 11 }, (_, i) => {
        const at = (along * i) / 10;
        return (
          <Fragment key={i}>
            {i > 0 && i < 10 ? (
              <div
                style={{
                  position: "absolute",
                  background: line,
                  ...(portrait
                    ? { left: 0, right: 0, top: at, height: 1 }
                    : { top: 0, bottom: 0, left: at, width: 1 }),
                }}
              />
            ) : null}
            <div
              style={{
                position: "absolute",
                fontFamily: plex.fontFamily,
                fontWeight: 500,
                fontSize: 11 * u * (portrait ? 1.3 : 1),
                letterSpacing: "0.04em",
                color: text,
                fontVariantNumeric: "tabular-nums",
                ...(portrait
                  ? {
                      right: 18 * u,
                      top: Math.min(
                        Math.max(at - 18 * u, 8 * u),
                        height - 26 * u,
                      ),
                    }
                  : {
                      bottom: 16 * u,
                      left: Math.min(
                        Math.max(at + 7 * u, 8 * u),
                        width - 30 * u,
                      ),
                    }),
              }}
            >
              {i * 10}
            </div>
          </Fragment>
        );
      })}
    </div>
  );

  const readout = (fg: string, muted: string) => (
    <div
      style={{
        position: "absolute",
        left: margin,
        top: margin,
        display: "flex",
        alignItems: "center",
        gap: 12 * u,
        fontFamily: plex.fontFamily,
        fontWeight: 500,
        fontSize: labelFs,
        letterSpacing: "0.06em",
        textTransform: "uppercase",
        color: fg,
      }}
    >
      <span
        style={{
          display: "grid",
          overflow: "hidden",
        }}
      >
        <span
          style={{
            gridArea: "1 / 1",
            transform: `translateY(${-swapT * 110}%)${glide(midway(swapT))}`,
          }}
        >
          {fromLabel}
        </span>
        <span
          style={{
            gridArea: "1 / 1",
            transform: `translateY(${(1 - swapT) * 110}%)${glide(midway(swapT))}`,
          }}
        >
          {toLabel}
        </span>
      </span>
      <span style={{ width: 24 * u, height: 1, background: muted }} />
      <span
        style={{
          color: muted,
          fontVariantNumeric: "tabular-nums",
        }}
      >
        {fmt(remaining)}%
      </span>
    </div>
  );

  const statStyle = {
    fontFamily,
    fontWeight,
    fontSize: statFs,
    lineHeight: 0.9,
    letterSpacing: "-0.05em",
    fontVariantNumeric: "tabular-nums",
    color: fg,
    whiteSpace: "nowrap",
  } as const;

  return (
    <AbsoluteFill
      style={{
        background: transparent ? "transparent" : (background ?? p.bg),
        overflow: "hidden",
      }}
    >
      {scale(p.tick, p.muted)}
      <div style={{ position: "absolute", inset: 0, opacity: intro }}>
        {readout(fg, p.muted)}
      </div>
      <div
        style={{
          position: "absolute",
          inset: 0,
          clipPath: statClip,
          opacity: interpolate(
            frame,
            [
              cutEl.start + cutEl.beat("showFrom"),
              cutEl.start + cutEl.beat("showTo"),
            ],
            [0, 1],
            CLAMP,
          ),
          zIndex: 2,
        }}
      >
        <ScaleLayer scale={zoom}>
          <div
            style={{
              position: "absolute",
              ...(portrait
                ? {
                    left: margin,
                    right: margin * 1.6,
                    bottom: margin,
                    height: Math.max(zone, height * 0.3) - margin,
                    justifyContent: "flex-end",
                  }
                : {
                    right: margin,
                    top: margin,
                    bottom: margin * 1.45,
                    width: Math.max(zone, width * 0.36) - margin * 1.6,
                    justifyContent: "flex-end",
                  }),
              display: "flex",
              flexDirection: "column",
              alignItems: portrait ? "flex-start" : "flex-end",
              textAlign: portrait ? "left" : "right",
            }}
          >
            <div
              style={{
                ...statStyle,
                marginRight: portrait ? 0 : -statFs * 0.04,
                marginLeft: portrait ? -statFs * 0.04 : 0,
              }}
            >
              {prefix}
              {fmt(counted)}
              {suffix}
            </div>
            <div
              style={{
                marginTop: statFs * 0.14,
                maxWidth: portrait
                  ? width - margin * 2
                  : Math.max(roomW, 300 * u),
                fontFamily,
                fontWeight: 400,
                fontSize: (portrait ? 46 : 34) * u,
                lineHeight: 1.12,
                letterSpacing: "-0.02em",
                color: fg,
                textWrap: "balance",
              }}
            >
              {words.map((w, k) => {
                const t = wordT(k);
                return (
                  <Fragment key={`${w}-${k}`}>
                    {k > 0 ? " " : null}
                    <span
                      style={{
                        display: "inline-block",
                        overflow: "hidden",
                        verticalAlign: "top",
                        paddingBottom: "0.12em",
                        marginBottom: "-0.12em",
                      }}
                    >
                      <span
                        style={{
                          display: "inline-block",
                          transform: `translateY(${(1 - t) * 105}%)${glide(midway(t))}`,
                        }}
                      >
                        {w}
                      </span>
                    </span>
                  </Fragment>
                );
              })}
            </div>
            {caption ? (
              <div
                style={{
                  marginTop: 16 * u,
                  fontFamily: plex.fontFamily,
                  fontWeight: 500,
                  fontSize: labelFs * (portrait ? 1.3 : 1),
                  letterSpacing: "0.04em",
                  textTransform: "uppercase",
                  color: p.muted,
                  opacity: capT,
                  transform: `translateY(${(1 - capT) * 8 * u}px)${glide(midway(capT))}`,
                }}
              >
                {caption}
              </div>
            ) : null}
          </div>
        </ScaleLayer>
      </div>

      <div
        style={{
          position: "absolute",
          inset: 0,
          clipPath: fieldClip,
          opacity: intro,
          background: [...blobs, p.fieldBg].join(", "),
        }}
      >
        {grain ? <Grain opacity={0.1} /> : null}
        {scale(p.fieldTick, p.fieldMuted)}
        {readout(p.fieldFg, p.fieldMuted)}
      </div>

      <div
        style={{
          position: "absolute",
          ...(portrait
            ? { left: 0, right: 0, top: edgeAt - 1 * u, height: 2 * u }
            : { top: 0, bottom: 0, left: edgeAt - 1 * u, width: 2 * u }),
          transform: edgeTravel
            ? `${portrait ? "translateY" : "translateX"}(${edgePos - edgeRest}px)`
            : undefined,
          background: p.edge,
          opacity: edgeO * intro,
          zIndex: 3,
        }}
      />
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The bar filling the frame, the scale's ticks, the cut sweeping the bar
// back, the readout swapping its label, the edge flashing as the cut lands,
// the number released from under the bar, the claim rising word by word
// and the caption. Frames on the 30 fps scene timeline, after `delay` and
// `speed`. The ids are public: a saved `timing` prop refers to them.

export type CutStatElementId =
  | "intro"
  | "fill"
  | "ticks"
  | "cut"
  | "swap"
  | `word:${number}`
  | "flash"
  | "release"
  | "caption";

export interface CutStatTimingProps {
  label?: string;
  stagger?: number;
}

export const DEFAULT_LABEL = "less time to a finished cut";

export function claimWords(label: string) {
  return label.split(/\s+/).filter(Boolean);
}

// `cut` sweeps the bar back over its length; the number shows from
// `showFrom` to `showTo` around its start. `flash` peaks at `peak`. Each
// `word:<i>` rises over its length and follows the one before; the first
// word, the swap, the flash, the release and the caption follow the cut.
export const cutStatTimeline = defineTimeline<
  CutStatElementId,
  CutStatTimingProps
>(({ label = DEFAULT_LABEL, stagger = 3 }) => {
  const words = claimWords(label);
  const elements: TimelineElement<CutStatElementId>[] = [
    { id: "intro", lane: "Bar", label: "Fade in", start: 0, length: 6 },
    { id: "fill", lane: "Bar", label: "Fill", start: 0, length: 15 },
    { id: "ticks", lane: "Scale", label: "Ticks", start: 4, length: 16 },
    {
      id: "cut",
      lane: "Bar",
      label: "Cut",
      start: 19,
      length: 32,
      beats: { showFrom: -1, showTo: 1 },
    },
    {
      id: "swap",
      lane: "Readout",
      label: "Swap label",
      start: 44,
      length: 12,
      follows: "cut",
    },
    ...words.map(
      (word, i): TimelineElement<CutStatElementId> => ({
        id: `word:${i}`,
        lane: "Claim",
        label: word,
        start: 47 + i * stagger,
        length: 18,
        follows: i > 0 ? `word:${i - 1}` : "cut",
      }),
    ),
    {
      id: "flash",
      lane: "Bar",
      label: "Flash",
      start: 49,
      length: 14,
      follows: "cut",
      beats: { peak: 3 },
    },
    {
      id: "release",
      lane: "Number",
      label: "Release",
      start: 53,
      length: 16,
      follows: "cut",
    },
    {
      id: "caption",
      lane: "Caption",
      label: "Caption",
      start: 63 + words.length * 2,
      length: 18,
      follows: "cut",
    },
  ];
  return elements.sort((a, b) => a.start - b.start);
});
